package com.smartattendance.service;

import com.smartattendance.dto.*;import com.smartattendance.exception.ResourceNotFoundException;import com.smartattendance.model.*;import com.smartattendance.repository.FacultyRepository;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;
@Service
public class FacultyService{private final FacultyRepository repo;private final UserService users;public FacultyService(FacultyRepository repo,UserService users){this.repo=repo;this.users=users;}public Page<FacultyResponse> search(String q,Pageable p){return(q==null||q.isBlank()?repo.findAll(p):repo.findByNameContainingIgnoreCaseOrEmployeeIdContainingIgnoreCaseOrDepartmentContainingIgnoreCase(q,q,q,p)).map(this::toResponse);}public FacultyResponse get(Long id){return toResponse(find(id));}public FacultyResponse create(FacultyRequest r){Faculty f=new Faculty();apply(f,r);return toResponse(repo.save(f));}public FacultyResponse update(Long id,FacultyRequest r){Faculty f=find(id);apply(f,r);return toResponse(repo.save(f));}public void delete(Long id){repo.delete(find(id));}public Faculty find(Long id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Faculty",id));}private void apply(Faculty f,FacultyRequest r){f.setEmployeeId(r.employeeId());f.setName(r.name());f.setEmail(r.email());f.setDepartment(r.department());f.setUser(r.userId()==null?null:users.find(r.userId()));}public FacultyResponse toResponse(Faculty f){return new FacultyResponse(f.getId(),f.getEmployeeId(),f.getName(),f.getEmail(),f.getDepartment(),f.getUser()==null?null:f.getUser().getId());}}
